 "Nivel": "Nibela",
 "<b style=\"font-size:25px;color:#47956b\">Nivel</b><br><span style=\"font-size:21px;color:#2e2308\">Para que no quede torcida.</span>": "<b style=\"font-size:25px;color:#47956b\">Nibela</b><br><span style=\"font-size:21px;color:#2e2308\">Okertuta gera ez dadin.</span>",
 "Gafas y guantes": "Betaurrekoak eta eskularruak",
